import{_ as o,C as t,o as i,c as s,E as a,a2 as c}from"./chunks/framework.BOeh4kYD.js";const h="/joinwell52/assets/six-governance-20260918/checking-the-checker.figure.en.svg",w=JSON.parse('{"title":"When an AI team fails, who checks the checker?","description":"","frontmatter":{"schema":"publication-candidate-article/v2","title":"When an AI team fails, who checks the checker?","date":"2026-09-18","published_date":"2026-09-18","column":"open-source-engineering","category":"daily","article_type":"experiment-report","edition":"research-center","research_question":"When an AI team fails, who checks the checker?","summary":"One of two answers is wrong, yet the score is 100%. Original evaluation code and public annotations show why tools that diagnose agent failures need checks of their own.","cover":"/assets/six-governance-20260918/checking-the-checker.cover-v1.png","language":"en","lifecycle":"Published","publication_authorized":true,"evidence_status":"Bounded original-code and public-artifact study; scope stated in text","pageClass":"six-governance-article"},"headers":[],"relativePath":"en/research/2026-09-18-checking-the-checker.md","filePath":"en/research/2026-09-18-checking-the-checker.md","lastUpdated":1789663032000}'),l={name:"en/research/2026-09-18-checking-the-checker.md"};function d(p,e,u,m,g,f){const r=t("ArticleCover"),n=t("ArticleTableScroll");return i(),s("div",null,[a(r,{image:"/assets/six-governance-20260918/checking-the-checker.cover-v1.png",kicker:"Open-source engineering · Experimental research",title:"When an AI team fails, who checks the checker?",summary:"One of two answers is wrong, yet the score is 100%. Original evaluation code and public annotations show why tools that diagnose agent failures need checks of their own.",version:"2026-09-18",languageHref:"/zh/research/2026-09-18-checking-the-checker",languageLabel:"中文"}),a(n,{language:"en"}),e[0]||(e[0]=c('<h1 id="when-an-ai-team-fails-who-checks-the-checker" tabindex="-1">When an AI team fails, who checks the checker? <a class="header-anchor" href="#when-an-ai-team-fails-who-checks-the-checker" aria-label="Permalink to &quot;When an AI team fails, who checks the checker?&quot;">​</a></h1><p>Two questions. One correct answer. A score of 100%.</p><p>This was not an AI confidently inventing a result. We ran a real open-source evaluation program with two synthetic predictions. For one case, the correct step was 1 and the predicted step was 10. The program checked whether the string “1” occurred inside “10” and counted it as correct. Integer equality would give this two-case set 50%.</p><p>Before asking another AI to explain why a team failed, we may need to check what its evaluation tools mean by “correct.”</p><h2 id="why-these-two-projects-mattered-to-us" tabindex="-1">Why these two projects mattered to us <a class="header-anchor" href="#why-these-two-projects-mattered-to-us" aria-label="Permalink to &quot;Why these two projects mattered to us&quot;">​</a></h2><p>Our research concerns governance of work shared among multiple agents: how to understand where a task went wrong beyond a final completion message.</p><p><a href="https://arxiv.org/abs/2503.13657v3" target="_blank" rel="noreferrer">MAST</a>, co-authored by Lakshya A. Agrawal, provides a vocabulary for classifying failures. <a href="https://arxiv.org/abs/2505.00212v3" target="_blank" rel="noreferrer">Who&amp;When</a>, by Shaokun Zhang and colleagues, asks which agent and which step were responsible. Classification and localization could both help engineering review.</p><p>We followed the papers into their repositories and public data. This was a bounded artifact study, not a rerun of their model experiments. We examined label meaning, scoring behavior, and whether a correct outcome necessarily implied an acceptable process.</p><h2 id="a-step-number-is-an-identifier" tabindex="-1">A step number is an identifier <a class="header-anchor" href="#a-step-number-is-an-identifier" aria-label="Permalink to &quot;A step number is an identifier&quot;">​</a></h2><p>The tested Who&amp;When evaluator uses substring membership. Because that operation is directional, we tested both directions and controls.</p><table tabindex="0"><thead><tr><th>Reference step</th><th>Prediction</th><th>Upstream scoring</th><th>Integer equality</th></tr></thead><tbody><tr><td>1</td><td>1</td><td>Correct</td><td>Correct</td></tr><tr><td>1</td><td>10</td><td>Correct</td><td>Incorrect</td></tr><tr><td>10</td><td>1</td><td>Incorrect</td><td>Incorrect</td></tr><tr><td>2</td><td>10</td><td>Incorrect</td><td>Incorrect</td></tr></tbody></table><p>We then passed a prediction file containing one false match and one exact match through the original command-line entry point. It reported 100%, confirming that the behavior survives the file parser and evaluation path.</p><p><img src="'+h+'" alt="The same two synthetic inputs receive different scores under two rules"></p><p><em>Figure 1. The same two synthetic cases score 100% with the original evaluator and 50% with integer equality. Source: attribution-cli-control.json and the original CLI control experiment; not a rescore of the paper’s results.</em></p><p>Another researcher had already raised the matching issue in <a href="https://github.com/ag2ai/Agents_Failure_Attribution/issues/14" target="_blank" rel="noreferrer">Issue #14</a>. Our contribution is a controlled replication, not a claim of discovery or a rejection of the paper.</p><p>We also inspected all 184 reference records. For 22, a different index within the recorded history length can contain the correct index as a substring. This describes possible inputs. <strong>It does not mean the model actually made 22 such errors.</strong> Without the corresponding original predictions, we cannot determine how much any published score changes.</p><p>Reference labels, predictions, and evaluator code are separate pieces of evidence. One cannot stand in for the others.</p><h2 id="the-same-category-number-can-mean-different-things" tabindex="-1">The same category number can mean different things <a class="header-anchor" href="#the-same-category-number-can-mean-different-things" aria-label="Permalink to &quot;The same category number can mean different things&quot;">​</a></h2><p>MAST exposed a different interpretation problem. At a pinned dataset revision, the public human-label file contains 19 records across annotation rounds: five with 18 categories, ten with 17, and four with 14.</p><p>These are not interchangeable schemas. Category <code>1.2</code> describes a reasoning–action inconsistency in earlier rounds and a role-specification violation in the final group. Combining records by numeric code alone would mix different phenomena.</p><p>Our data check agrees with the existing report in <a href="https://github.com/multi-agent-systems-failure-taxonomy/MAST/issues/18" target="_blank" rel="noreferrer">Issue #18</a>. A taxonomy evolving during research is unsurprising. What downstream users need is an explicit version and a justified mapping, where one exists.</p><p>We therefore did not collapse these records into a tidy ranking of common multi-agent failures. Preserving the versions was more informative than producing a number whose meaning was unclear.</p><h2 id="a-correct-answer-can-coexist-with-a-process-problem" tabindex="-1">A correct answer can coexist with a process problem <a class="header-anchor" href="#a-correct-answer-can-coexist-with-a-process-problem" aria-label="Permalink to &quot;A correct answer can coexist with a process problem&quot;">​</a></h2><p>We separately inspected all 31 immediate AG2 files ending in <code>human.json</code> at the fixed repository commit. These use an older 22-label scheme, so we did not merge them into the 14-category taxonomy.</p><p>Seven records were labeled as making no attempt to verify the outcome; nineteen as having an insufficiently critical evaluator. The groups may overlap. They cannot be added into a failure rate. One record was marked both correct in outcome and problematic for stopping behavior and ignoring another agent’s suggestion.</p><p>Users may recognize that distinction: an agent correctly explains that information is missing, while another role continues asking it to finish. The answer can remain defensible while the collaboration wastes effort and lacks a clear basis for stopping.</p><p>These are observations about released annotations, not new human judgments or agent runs. They motivate two separate questions: was the answer correct, and was the work carried out in a controllable, explainable way?</p><h2 id="useful-checks-must-themselves-be-checkable" tabindex="-1">Useful checks must themselves be checkable <a class="header-anchor" href="#useful-checks-must-themselves-be-checkable" aria-label="Permalink to &quot;Useful checks must themselves be checkable&quot;">​</a></h2><p>Failure classification and attribution make vague complaints about reliability more concrete. Before their outputs inform decisions, however, preserve the dataset revision, label definitions, raw predictions, and scoring rules.</p><p>A cheap additional safeguard is a small set of known-answer controls: similar-looking identifiers, missing predictions, and differing label versions. Verify the checker before relying on its conclusions.</p><p>For researchers, our next question is whether explicit label mappings and exact-match scoring can be released together for comparison. For users, we would like concrete examples of correct answers reached through repeated work, unclear stopping, or missing verification. A specific handoff is more useful evidence than a general claim that a team “lost control.”</p><p>This study supports a method for checking evidence. It does not establish that any particular governance protocol has solved these problems.</p><p>Study date: 17 September 2026. See the <a href="https://github.com/joinwell52-AI/joinwell52/blob/d258d0b925af198f0920fc6e897c390e02979900/research/manual-runs/2026-09-17-six-governance/00-report.md" target="_blank" rel="noreferrer">experiment report</a> for commits, hashes, scripts, and limitations. Synthetic controls, artifact inspection, and existing upstream reports are distinguished throughout; we did not recompute the paper’s full results.</p><p><a href="https://github.com/joinwell52-AI/joinwell52" target="_blank" rel="noreferrer">Research repository</a></p>',34))])}const k=o(l,[["render",d]]);export{w as __pageData,k as default};
